route_witness_mappings.child_source:
let root = Path(args[0])
archive.tar_create(fp"{root}/payload.tar", root, [p"member"])
assert fp"{root}/payload.tar".exists()?

let parsed = "21".parse_int()
let result = try { parsed? }
assert result == Ok(21)

error RouteOracleError = Failed
let result: Result[Int, RouteOracleError] = Err(.Failed("failed"))
assert result is Err(_)

error RouteError = Failed(message: Str)
let result: Result[Int, RouteError] = Err(RouteError.Failed(message: "failed"))
assert result is Err(_)

type Item = {value: Int}
pure read_item(item: Item) -> Int { item.value }
assert read_item({value: 41}) == 41

let root = Path(args[0])
let files = fs.files(root, gitignore: false, stat: false, hidden: false, exts: ["txt"])?.collect()
assert files.len() == 1 and files[0].name == "visible.txt"

let root = Path(args[0])
let children = fs.children(root, ordered: true)?.collect()
assert children.len() == 1 and children[0].name == "entry"

let directory = Path(args[0])
tempdir scratch at directory { assert scratch.exists()? }
assert !directory.exists()?

let target = Path(args[0])
let result = tempdir scratch at target { assert false }
test.error_kind(result, "fs-remove")

let root = Path(args[0])
let walked = fs.walk(root, gitignore: false, stat: false, hidden: false)?.collect()
assert walked.len() == 2
assert walked |> any .name == "entry"

pure increment(value: Int) -> Int { value + 1 }
let alias = increment
assert alias(41) == 42

proc selected_index() [io] -> Int { return 1 }
let values = [10, 20]
assert values[selected_index()] == 20

proc middle() -> List[Int] { return [2, 3] }
let values = [1, @middle(), 4]
assert values.len() == 4 and values[1] == 2 and values[2] == 3

let target = Path(args[0])
target.mkdir()?
assert target.exists()?

let target = Path(args[0])
target.remove(missing_ok: false)?
assert !target.exists()?

let target = Path(args[0])
target.write("payload")?
assert target.read_text()? == "payload"

let result = Ok(7)
let selected = if let Ok(value) = result { value } else { 0 }
assert selected == 7

type RouteConstantBox = {values: Map[Int, Int] = {[42]: 7}}
let box = RouteConstantBox()
assert box.values.get(42)? == 7

proc route_proc_target(value: Int) -> Int { value + 1 }
let handle: Proc = route_proc_target
assert handle.call(20)?.require(Int)? == 21

let entry = {name: "route", count: 2}
assert entry.name == "route"
assert entry.count == 2

type RouteDetails = {count: Int}
type RouteRecord = {name: Str, details: RouteDetails}
proc route_original_record() -> RouteRecord { return {name: "before", details: {count: 1}} }
let original = route_original_record()
let changed = {...original, details.count: 2}
assert changed.name == "before"
assert changed.details.count == 2

error RouteOracleError = Failed
let missing: Result[Int, RouteOracleError] = Err(.Failed("missing"))
assert (missing ?? 9) == 9

let command = process.command_argv("true", ["true"])
let child = spawn command?
assert (wait child?).exited_with(0)

let word = "green"
let selected = match word {
  "green" => "go"
  else => "stop"
}
assert selected == "go"

enum Choice { Selected(Int) }
let selected: Choice = Selected(42)
match selected { Selected(value) => assert value == 42 }

enum RouteTag { Ready, Busy }
proc route_match_tag() -> RouteTag { return Ready }
let tag = route_match_tag()
let selected = match tag {
  Ready() => "ready"
  Busy() => "busy"
}
assert selected == "ready"

pure unit() -> Unit {}
let value: Any = unit()
assert value is Unit
